import os
from google.cloud import documentai_v1 as documentai

def extract_receipt_fields(payload, config=None):
    config = config or {}
    project_id = config.get("project_id") or os.environ["GOOGLE_CLOUD_PROJECT"]
    location = config.get("location") or os.environ.get("DOCUMENTAI_LOCATION", "us")
    processor_id = config.get("processor_id") or os.environ["DOCUMENTAI_PROCESSOR_ID"]

    client = documentai.DocumentProcessorServiceClient()
    name = client.processor_path(project_id, location, processor_id)

    mime_type = config.get("mime_type") or payload.get("mime_type") or "application/pdf"
    content = payload.get("content")
    if content is None:
        file_path = payload.get("file_path")
        if not file_path:
            raise ValueError("payload must include 'content' bytes or 'file_path'")
        with open(file_path, "rb") as f:
            content = f.read()

    raw_document = documentai.RawDocument(content=content, mime_type=mime_type)
    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    document = client.process_document(request=request).document

    entities = {}
    items = []
    for entity in getattr(document, "entities", []):
        etype = (entity.type_ or "").lower()
        mention = (entity.mention_text or "").strip()

        if etype == "line_item":
            item_data = {}
            for prop in getattr(entity, "properties", []):
                ptype = (prop.type_ or "").lower()
                pval = (prop.mention_text or "").strip()
                if ptype:
                    item_data[ptype] = pval
            if not item_data and mention:
                item_data["description"] = mention
            if item_data:
                items.append(item_data)
        elif etype in {"supplier_name", "merchant_name", "vendor_name"} and mention:
            entities["merchant"] = mention
        elif etype in {"total_tax", "tax"} and mention:
            entities["tax"] = mention
        elif etype in {"total_amount", "total", "amount_due"} and mention:
            entities["total"] = mention

    result = {
        "merchant": entities.get("merchant"),
        "tax": entities.get("tax"),
        "total": entities.get("total"),
        "items": items,
    }
    return result
